(async function(){
'use strict';const M=SpaceFoxM,R=SpaceFoxMR,D=SpaceFoxMarkerData,$=s=>document.querySelector(s),bed=$('#bed');
let campaign={schemaVersion:1,protocol:'launch-marker-v1',policy:M.policy,training:D.scenes,generations:[],controls:[],assets:{}},busy=false,jobs=[],cursor=-1,painted=null;
const all=()=>campaign.generations.flatMap(g=>g.candidates),results=()=>campaign.generations.flatMap(g=>g.results);
function show(cs){$('#gallery').replaceChildren(...cs.map(c=>{const a=document.createElement('article');a.className='card';const h=document.createElement('h2');h.textContent=c.id+' · '+c.family+' / '+c.kind;const p=document.createElement('div');p.className='preview';p.append(R.render(c,D.hero));a.append(h,p);return a;}));}
function summary(){$('#summary').textContent=campaign.generations.map(g=>g.name+': '+g.results.map(r=>r.id+' '+r.failedScenes+'/'+r.trials).join(' · ')).join('\n');}
async function measure(cs,scenes){if(busy)throw Error('busy');busy=true;const records=[],rs=[];try{for(const c of cs){const trials=[];for(const s of scenes){const face=R.render(c,s);bed.replaceChildren(face);const out=await R.measure(face,c,s),observation=out.observation,t=M.evaluate(observation,s,c);let assetKey=null;if(out.assets){const data=JSON.stringify(out.assets),hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(data));assetKey=Array.from(new Uint8Array(hash)).map(n=>n.toString(16).padStart(2,'0')).join('');campaign.assets[assetKey]=out.assets;}const rec={candidate:c.id,scene:s.id,failures:t.failures,observation,assetKey};records.push(rec);trials.push(rec);}rs.push(M.summarize(c,trials));$('#status').textContent=`Измерено ${rs.length}/${cs.length} × ${scenes.length} сцен`;await new Promise(r=>setTimeout(r,0));}return {results:rs,records};}finally{busy=false;bed.replaceChildren();}}
async function stage(cs,name){M.validate(cs,all());const out=await measure(cs,D.scenes);campaign.generations.push({name,candidates:cs,...out});summary();show(cs);$('#status').textContent=name+' завершено: '+out.results.filter(r=>!r.failedScenes).length+'/'+cs.length+' геометрия/маски. Снимки и локализация отдельно.';}
const guard=fn=>async()=>{try{await fn();}catch(e){$('#status').textContent=String(e.stack);}};
$('#g1').onclick=guard(()=>stage([...M.controls(),...M.generationOne()],'G1+old'));
$('#g2').onclick=guard(()=>stage(M.generationTwo(all(),results()),'G2'));
$('#g3').onclick=guard(()=>stage(M.generationThree(all(),results()),'G3'));
$('#hero').onclick=guard(async()=>{const cs=all().filter(c=>!campaign.controls.some(g=>g.name==='authorNative'&&g.candidateIds.includes(c.id))),out=await measure(cs,[D.hero]);campaign.controls.push({name:'authorNative',candidateIds:cs.map(c=>c.id),scenes:[D.hero],...out});$('#status').textContent='Съёмочная сцена: '+cs.length+' точных DOM/mask records';});
$('#all').onclick=()=>show(all());$('#final').onclick=guard(async()=>{const selection=await(await fetch('final-selection.json')).json();show(selection.candidates);$('#status').textContent='Пять выбранных направлений из G2/G3; подробные границы проверки — в отчёте.';});
$('#export').onclick=guard(async()=>{const blob=new Blob([JSON.stringify(campaign)]),gz=await new Response(blob.stream().pipeThrough(new CompressionStream('gzip'))).blob(),a=document.createElement('a');a.href=URL.createObjectURL(gz);a.download='marker-campaign.json.gz';a.click();});
$('#load').onclick=guard(async()=>{const r=await fetch('../../openspec/changes/make-launch-site-obvious/evidence/campaign.json.gz');campaign=JSON.parse(await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).text());summary();show(all().slice(-10));$('#status').textContent='Сохранённый прогон загружен';});
$('#control').onclick=guard(async()=>{const ids=$('#ids').value.split(',').map(s=>s.trim()),cs=ids.map(id=>all().find(c=>c.id===id)),scenes=JSON.parse($('#scenes').value).scenes;if(cs.some(c=>!c)||new Set(ids).size!==ids.length||scenes.length!==24)throw Error('24 scenes/known distinct IDs required');const out=await measure(cs,scenes);campaign.controls.push({name:$('#phase').value,candidateIds:ids,scenes,...out});$('#status').textContent=$('#phase').value+': '+out.results.map(r=>r.id+' '+r.failedScenes+'/24').join(' · ');show(cs);});
function getScene(id){return [D.hero,...D.scenes,...campaign.controls.flatMap(g=>g.scenes)].find(s=>s.id===id);}
function capture(){if(cursor>=jobs.length){$('#captureMeta').textContent='DONE '+jobs.length;return;}const board=jobs[cursor],out=[];if(painted!==board.group){$('#capture').replaceChildren();painted=board.group;for(const [i,j]of board.trials.entries()){const c=all().find(c=>c.id===j.candidate),s=getScene(j.scene);if(!c||!s||!M.sizes.includes(j.size))throw Error('invalid job');const face=R.render(c,s),columns=Math.floor((innerWidth-32)/(j.size+8));Object.assign(face.style,{position:'absolute',left:(i%columns)*(j.size+8)+'px',top:Math.floor(i/columns)*(j.size+8)+'px',transform:`scale(${j.size/390})`});$('#capture').append(face);}}
for(const [i,j]of board.trials.entries()){const c=all().find(c=>c.id===j.candidate),s=getScene(j.scene),face=$('#capture').children[i];R.visibility(face,c,board.on);const r=face.getBoundingClientRect();out.push({...j,on:board.on,rep:board.rep,faceRect:{x:r.x,y:r.y,w:r.width,h:r.height},nonMarker:R.nonMarker(face,c),snapshot:s.fixture.point?R.snapshot(face,c):null});}
$('#captureMeta').textContent=JSON.stringify({index:cursor,group:board.group,viewport:[innerWidth,innerHeight],dpr:devicePixelRatio,trials:out});$('#captureIndex').textContent=`Кадр ${cursor+1}/${jobs.length}`;}
$('#prepare').onclick=guard(async()=>{jobs=await(await fetch($('#jobs').value)).json();cursor=0;document.body.classList.add('capture');capture();});$('#next').onclick=guard(async()=>{cursor++;capture();});$('#exit').onclick=()=>{document.body.classList.remove('capture');painted=null;};
await Promise.all([...new Set(Object.values(SpaceFoxF.fonts))].map(f=>document.fonts.load(`600 80px '${f}'`)));await document.fonts.load("500 21px 'Noto Sans'",'Россия USA');await document.fonts.ready;show(M.controls());$('#status').textContent='Готово · 30 → 20 → 10 + пять прежних контролей';
})();
